import assert from"assert";import{assertIsValidDependencyName}from"../../common/assertIsValidDependencyName.js";import{production}from"../../common/deployment/production.js";import getOption from"./util/getOption.js";(async()=>{const repo=getOption("repo");assert(repo,"Requires specifying a repository with --repo={{REPOSITORY}}");assert(getOption("branch"),"Requires specifying a branch with --branch={{BRANCH}}");assertIsValidDependencyName(repo);await production(repo,getOption("branch"),{noninteractive:!!getOption("noninteractive"),redeploy:!!getOption("redeploy"),message:getOption("message")});process.exit(0)})();